import{_ as s,l as i,o as e,c as o,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"评测方差与随机种子","description":"","frontmatter":{"title":"评测方差与随机种子","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eval-variance-seed.md","filePath":"llm/eval-variance-seed.md","lastUpdated":1789023840000}'),E={name:"llm/eval-variance-seed.md"};function A(c,a,m,u,_,k){const l=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="评测方差与随机种子" tabindex="-1">评测方差与随机种子 <a class="header-anchor" href="#评测方差与随机种子" aria-label="Permalink to &quot;评测方差与随机种子&quot;">​</a></h1><div class="epigraph"><p>温度非零时，一次解码是随机变量；智能体再叠一层环境种子。只报一个点估计，等于把噪声当成模型差。</p><footer>—— 对照 Pass@k、多次独立评测的置信区间；以及解码与数据划分的可复现约定</footer></div><p><a href="/llm/agent-eval-protocol">智能体评测协议</a> 冻结了环境与预算。本课补仍被当成「实现细节」的噪声源：<strong>解码种子、温度、评测题抽样、以及 RL 评测时的采样条数</strong>。Arena 的不确定度来自对战次数；这里来自生成随机性。缺口是：同一检查点、同一协议，换种子可以改名次。后课工具训练默认你会用多次运行或 pass@k 说话，而不是一次 greedy 的运气。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记一次评测为 \\(S(\\theta,\\xi)\\)，\\(\\xi\\) 含：解码 RNG、环境 RNG、题目子集、工具延迟抖动。Greedy（温度 0、无 tie-break 噪声）把解码项关掉，仍留下环境与数据划分。温度 0.7 的单次 GSM8K 可以在合理范围内抖好几个点；代码 pass@1 更抖。论文用单次采样对比两个差 1 分的模型，胜负没有定义。</p><p>智能体上 \\(\\xi\\) 更大：同一计划遇到工具超时与否。协议若允许抖动而不重复实验，分数测的是基础设施天气。需要：重复次数 \\(n\\)、汇总函数（均值、中位数、pass@k）、以及是否共享种子表。</p><h3 id="种子表是协议的一部分" tabindex="-1">种子表是协议的一部分 <a class="header-anchor" href="#种子表是协议的一部分" aria-label="Permalink to &quot;种子表是协议的一部分&quot;">​</a></h3><p>「seed=42」只钉解码器是不够的。数据加载 shuffle、并行下非确定 GPU 归约、MoE 路由的随机结、FlashAttention 的非确定核，都会让 greedy 也不复现。科学复现应声明：确定性算法是否开启、允许的非确定性核、以及评测是否在同一硬件。做不到完全确定时，<strong>用多次运行的分布代替假确定</strong>。<span class="marginnote">Pass@k 估计的是 \\(k\\) 次独立尝试中至少一次成功的概率，不是把 \\(k\\) 次里最好的那次当主结果却写作 pass@1。训练时拒绝采样用 \\(k\\) 条、评测用 1 条，要写清楚，否则闭环课的数字无法对照评测课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="重复、汇总与配对比较" tabindex="-1">重复、汇总与配对比较 <a class="header-anchor" href="#重复、汇总与配对比较" aria-label="Permalink to &quot;重复、汇总与配对比较&quot;">​</a></h3><p>回归评测：温度 0 的自动集跑 1 次作 CI 烟雾；发布表对关键集跑 \\(n\\ge 3\\) 个解码种子（或 \\(n\\) 次环境重置），报均值与区间。代码与数学生成报 pass@1 与 pass@k（\\(k\\) 与产品重试一致）。智能体报 \\(n\\) 次完整 rollout 的成功率均值，环境种子写入协议哈希。</p><p>比较两个模型：用配对（同一 \\(\\xi\\) 表）减少方差。非配对的独立种子会把 \\(\\xi\\) 差算进模型差。题集很大时，可对题做 bootstrap 估题目抽样方差，与解码方差分开报——两者指导的动作不同：前者扩题，后者降温度或增 \\(n\\)。</p>',12)),(e(),n(h,null,{default:r(()=>[p(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20XI%5B%22xi%EF%BC%9A%E8%A7%A3%E7%A0%81%20%2F%20%E7%8E%AF%E5%A2%83%20%2F%20%E9%A2%98%E7%9B%AE%22%5D%20--%3E%20RUN%5B%22%E9%87%8D%E5%A4%8D%20n%20%E6%AC%A1%22%5D%0A%20%20RUN%20--%3E%20AGG%5B%22%E5%9D%87%E5%80%BC%E3%80%81%E5%8C%BA%E9%97%B4%E3%80%81pass%40k%22%5D%0A%20%20AGG%20--%3E%20CMP%5B%22%E9%85%8D%E5%AF%B9%E7%A7%8D%E5%AD%90%E8%A1%A8%E6%AF%94%E8%BE%83%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20AGG%20--%3E%20SPLIT%5B%22%E6%8B%86%E5%BC%80%E9%A2%98%E7%9B%AE%E6%96%B9%E5%B7%AE%E4%B8%8E%E8%A7%A3%E7%A0%81%E6%96%B9%E5%B7%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>温度升高，解码方差升、探索升。产品解码与评测解码必须一致，否则你在优化一个不过线的分布。RL 训练温度高于评测温度时，评测会系统性偏高或偏低，取决于任务。应在表中写「eval temperature」。</p><p>小样本人评的评分员方差通常大于解码方差。这时加解码重复是浪费；应加题或加评分员。自动集则相反。仪器课选人还是自动，本课选 \\(n\\) 花在哪一维随机源上。</p><p><span class="marginnote">长 CoT 的长度本身是随机的，准确率与长度相关，单次运行的「又长又对」会被误读成能力。应报准确率–长度联合，或固定预算评测（长度课已要求）。种子只解解码噪声，不解预算混淆。</span></p><h3 id="与污染、过拟合的关系" tabindex="-1">与污染、过拟合的关系 <a class="header-anchor" href="#与污染、过拟合的关系" aria-label="Permalink to &quot;与污染、过拟合的关系&quot;">​</a></h3><p>反复在同一小 dev 上用很多种子调解码参数，是另一种过拟合。种子搜索应在真正 held-out 上只做一次确认。把「幸运种子」写进配置当默认，等于把 \\(\\xi\\) 吃进模型卡。发布配置应是事先声明的解码器，不是事后挑的。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>完全确定性在 MoE + 高效核上可能不可得。工程选择是：CI 用低 \\(n\\) 快测挡回归；发布用高 \\(n\\) 付钱买区间。不要让 CI 的单次 greedy 成为唯一数字源，否则合并请求会为 0.3 分抖动吵架。</p><p>多语言、多任务加权总分会把方差不同的子项加在一起。应先分项再加权，并对每项有自己的 \\(n\\)。智能体活网评测的方差含网页改版，区间会跨周失效——回到协议课：活网不当主表。</p><p><span class="marginnote">μP 与训练种子是另一件事：训练不可复现不等于评测可以不报 \\(n\\)。两者都要，但本课只约束评测实验设计。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>评测是 \\(S(\\theta,\\xi)\\)；必须规定 \\(\\xi\\) 的哪些维被重复、如何汇总。</li><li>发布表用多次种子或 pass@k，配对比较模型；禁止幸运种子默认。</li><li>拆开题目抽样方差与解码方差，动作不同。</li><li>评测温度与产品解码一致；长链还要固定预算。</li><li>不确定核存在时用分布说话，不假装 greedy 可复现。</li><li>出处：pass@k 估计传统；实验设计中的配对与重复测量。</li></ul>',12))])}const B=s(E,[["render",A]]);export{x as __pageData,B as default};
